// internal/restful/v2/search.go line 170-205
func (h *SearchHandler) Search(ctx context.Context, req *restful.SearchReq) (*restful.SearchResp, error) {
    // Parse groupParams without field type validation
    groupParams := req.GroupParams
    if groupParams != nil {
        groupByField := groupParams.GroupByField  // No type check: accepts any field name
        groupSize := groupParams.GroupSize
        // Direct pass-through to search executor
        searchReq.GroupByField = groupByField
        searchReq.GroupSize = groupSize
    }
    // Search executor handles grouping internally - may ignore vector grouping
    return h.executor.Search(ctx, searchReq)
}
